import React from 'react';
import { LayoutDashboard, FileSearch, Send, User, Settings, LogOut } from 'lucide-react';

const Sidebar = ({ activeTab, setActiveTab }) => {
  const menuItems = [
    { id: 'dashboard', label: 'لوحة التحكم', icon: <LayoutDashboard size={22} /> },
    { id: 'offers', label: 'استكشاف العروض', icon: <FileSearch size={22} /> },
    { id: 'applications', label: 'طلباتي', icon: <Send size={22} /> },
    { id: 'profile', label: 'الملف الشخصي', icon: <User size={22} /> },
    { id: 'settings', label: 'الإعدادات', icon: <Settings size={22} /> },
  ];

  return (
    <div className="w-64 h-screen bg-white border-l border-slate-100 flex flex-col p-6 fixed right-0 top-0" dir="rtl">
      {/* Logo */}
      <div className="text-2xl font-black text-blue-600 mb-10 px-4">
        Stag.io
      </div>

      {/* Navigation Links */}
      <nav className="flex-1 space-y-2">
        {menuItems.map((item) => (
          <button
            key={item.id}
            onClick={() => setActiveTab(item.id)}
            className={`w-full flex items-center gap-3 px-4 py-3 rounded-xl font-bold transition-all ${
              activeTab === item.id 
              ? 'bg-blue-600 text-white shadow-lg shadow-blue-100' 
              : 'text-slate-500 hover:bg-slate-50'
            }`}
          >
            {item.icon}
            <span>{item.label}</span>
          </button>
        ))}
      </nav>

      {/* Logout Button */}
      <button className="flex items-center gap-3 px-4 py-3 text-red-500 font-bold hover:bg-red-50 rounded-xl transition-all mt-auto">
        <LogOut size={22} />
        <span>تسجيل الخروج</span>
      </button>
    </div>
  );
};

export default Sidebar;
